-- Mr Krabs · migration 0002 — ledger legs, category keys, typed settings, recurring templates
-- Generated by dbbuild on 2026-11-22
-- Proposal: docs/db-review/proposal/proposal.md (rev 3, accepted by the owner on 2026-11-22)
-- Design:   docs/db-review/design/design.md + schema.sql (rev 3)
-- Engine:   SQLite 3.45+ (rusqlite 0.37 bundled), STRICT tables
-- Mode:     migration of schema v1 (0001_init.sql) to v2
-- Status:   complete
--
-- Runner contract (mrk-store Store::migrate): this script runs inside ONE transaction with
-- PRAGMA foreign_keys = OFF (set before the transaction, where it takes effect), and
-- PRAGMA foreign_key_check must return no rows before commit. That is SQLite's documented
-- table-rebuild procedure: create <t>_new, copy, drop <t>, rename <t>_new to <t>.
-- Any failing guard, CHECK, UNIQUE or FK aborts the whole migration; nothing is half-applied.
-- Storage + integrity only (ADR-0002): no triggers, views, procedures or UDFs.
-- CREATE TABLE / CREATE INDEX text is copied verbatim from the design schema, so a migrated database
-- equals a fresh build of schema.sql (checked by mrk-store's schema-equivalence test).

-- ───────────────────────── 1. Guards (abort before any change) ─────────────────────────
-- A guard is a temp table whose CHECK rejects a failed condition; the error names the guard.

CREATE TEMP TABLE guard_0002_g1 (ok INTEGER NOT NULL, CONSTRAINT "G1: category must be empty: name_key needs the Rust normalize()" CHECK (ok = 1));
INSERT INTO guard_0002_g1 (ok) SELECT (SELECT count(*) FROM category) = 0;

CREATE TEMP TABLE guard_0002_g2 (ok INTEGER NOT NULL, CONSTRAINT "G2: recurring_rule must be empty: template_json has no defined format to convert" CHECK (ok = 1));
INSERT INTO guard_0002_g2 (ok) SELECT (SELECT count(*) FROM recurring_rule) = 0;

CREATE TEMP TABLE guard_0002_g3 (ok INTEGER NOT NULL, CONSTRAINT "G3: every entry with shares must have exactly one live posting currency" CHECK (ok = 1));
INSERT INTO guard_0002_g3 (ok) SELECT NOT EXISTS (SELECT 1 FROM entry_share s
                   WHERE (SELECT count(DISTINCT p.currency_code) FROM posting p
                          WHERE p.entry_id = s.entry_id AND p.deleted = 0) <> 1);

CREATE TEMP TABLE guard_0002_g4 (ok INTEGER NOT NULL, CONSTRAINT "G4: is_shared must agree with the presence of live entry_share rows" CHECK (ok = 1));
INSERT INTO guard_0002_g4 (ok) SELECT NOT EXISTS (SELECT 1 FROM journal_entry e
                   WHERE e.is_shared <> EXISTS (SELECT 1 FROM entry_share s
                                                WHERE s.entry_id = e.id AND s.deleted = 0));

-- ───────────────────────── 2. Reference data ─────────────────────────
