-- ───────────────────────── 3. Rebuilt tables: create <t>_new and copy ─────────────────────────

CREATE TABLE household_new (
    id                 TEXT PRIMARY KEY,
    name               TEXT NOT NULL,
    base_currency_code TEXT NOT NULL REFERENCES currency(code),
    budget_mode        TEXT NOT NULL DEFAULT 'per_installment' CHECK (budget_mode IN ('at_purchase','per_installment')),
    locale             TEXT NOT NULL DEFAULT 'es-CL' CHECK (locale IN ('es-CL','en')),
    hlc INTEGER NOT NULL, hlc_device TEXT NOT NULL, deleted INTEGER NOT NULL DEFAULT 0 CHECK (deleted IN (0,1))
) STRICT;
INSERT INTO household_new (id, name, base_currency_code, budget_mode, locale, hlc, hlc_device, deleted)
SELECT h.id, h.name,
       coalesce((SELECT s.value FROM household_setting s WHERE s.key = 'base_currency' AND s.deleted = 0), 'CLP'),
       coalesce((SELECT s.value FROM household_setting s WHERE s.key = 'budget_mode'   AND s.deleted = 0), 'per_installment'),
       coalesce((SELECT s.value FROM household_setting s WHERE s.key = 'locale'        AND s.deleted = 0), 'es-CL'),
       h.hlc, h.hlc_device, h.deleted
FROM household h;

CREATE TABLE account_new (
    id               TEXT PRIMARY KEY,
    name             TEXT NOT NULL,
    kind             TEXT NOT NULL REFERENCES account_kind(code),              -- [D-24]
    currency_code    TEXT NOT NULL REFERENCES currency(code),
    scope            TEXT NOT NULL CHECK (scope IN ('personal','household')),
    owner_member_id  TEXT REFERENCES member(id),
    visibility       TEXT NOT NULL                                           -- [D-12] no default: Rust sets it per scope (T-25)
                       CHECK (visibility IN ('private','shared_summary','shared_full')),
    institution      TEXT,
    number_mask      TEXT,
    credit_limit_minor INTEGER CHECK (credit_limit_minor >= 0),
    statement_day    INTEGER CHECK (statement_day BETWEEN 1 AND 31),
    due_day          INTEGER CHECK (due_day BETWEEN 1 AND 31),
    linked_account_id TEXT REFERENCES account(id),
    is_archived      INTEGER NOT NULL DEFAULT 0 CHECK (is_archived IN (0,1)),
    sort_order       INTEGER NOT NULL DEFAULT 0,
    hlc INTEGER NOT NULL, hlc_device TEXT NOT NULL, deleted INTEGER NOT NULL DEFAULT 0 CHECK (deleted IN (0,1)),
    UNIQUE (id, currency_code),                                                -- [D-04] target of composite FKs
    CHECK ((scope = 'personal' AND owner_member_id IS NOT NULL) OR (scope = 'household' AND owner_member_id IS NULL)),
    CHECK (visibility = 'shared_full' OR scope = 'personal'),
    -- [D-09] credit-card attributes only on credit cards; a section never links to itself
    CHECK (kind = 'credit_card' OR (credit_limit_minor IS NULL AND statement_day IS NULL AND due_day IS NULL AND linked_account_id IS NULL)),
    CHECK (linked_account_id IS NULL OR linked_account_id <> id)
) STRICT;
INSERT INTO account_new (id, name, kind, currency_code, scope, owner_member_id, visibility, institution,
       number_mask, credit_limit_minor, statement_day, due_day, linked_account_id, is_archived, sort_order,
       hlc, hlc_device, deleted)
SELECT id, name, kind, currency_code, scope, owner_member_id, visibility, institution,
       number_mask, credit_limit_minor, statement_day, due_day, linked_account_id, is_archived, sort_order,
       hlc, hlc_device, deleted
FROM account;

CREATE TABLE category_new (
    id             TEXT PRIMARY KEY,
    parent_id      TEXT,
    kind           TEXT NOT NULL CHECK (kind IN ('income','expense')),
    name           TEXT NOT NULL CHECK (length(trim(name)) > 0),
    name_key       TEXT NOT NULL CHECK (length(name_key) > 0),
    icon           TEXT,
    seed_key       TEXT UNIQUE,
    merged_into_id TEXT,
    is_archived    INTEGER NOT NULL DEFAULT 0 CHECK (is_archived IN (0,1)),
    sort_order     INTEGER NOT NULL DEFAULT 0,
    hlc INTEGER NOT NULL, hlc_device TEXT NOT NULL, deleted INTEGER NOT NULL DEFAULT 0 CHECK (deleted IN (0,1)),
    UNIQUE (id, kind),                                                         -- composite FK target
    FOREIGN KEY (parent_id, kind)      REFERENCES category(id, kind),          -- child kind = parent kind
    FOREIGN KEY (merged_into_id, kind) REFERENCES category(id, kind),          -- merge only within a kind
    CHECK (parent_id IS NULL OR parent_id <> id),
    CHECK (merged_into_id IS NULL OR (deleted = 1 AND merged_into_id <> id))
) STRICT;
-- category: guard G1 proved it empty (name_key needs the Rust normalize()), so nothing to copy.

CREATE TABLE payee_new (
    id          TEXT PRIMARY KEY,
    name        TEXT NOT NULL CHECK (length(trim(name)) > 0),
    default_category_id TEXT REFERENCES category(id),
    hlc INTEGER NOT NULL, hlc_device TEXT NOT NULL, deleted INTEGER NOT NULL DEFAULT 0 CHECK (deleted IN (0,1))
) STRICT;
INSERT INTO payee_new (id, name, default_category_id, hlc, hlc_device, deleted)
SELECT id, name, default_category_id, hlc, hlc_device, deleted FROM payee;

CREATE TABLE tag_new (
    id    TEXT PRIMARY KEY,
    name  TEXT NOT NULL CHECK (length(trim(name)) > 0),
    hlc INTEGER NOT NULL, hlc_device TEXT NOT NULL, deleted INTEGER NOT NULL DEFAULT 0 CHECK (deleted IN (0,1))
) STRICT;
INSERT INTO tag_new (id, name, hlc, hlc_device, deleted)
SELECT id, name, hlc, hlc_device, deleted FROM tag;

CREATE TABLE fx_rate_new (
    id           TEXT PRIMARY KEY,
    base_code    TEXT NOT NULL REFERENCES currency(code),
    quote_code   TEXT NOT NULL REFERENCES currency(code),
    rate_date    TEXT NOT NULL CHECK (rate_date GLOB '[0-9][0-9][0-9][0-9]-[0-1][0-9]-[0-3][0-9]'),
    rate         TEXT NOT NULL,
    source       TEXT NOT NULL CHECK (source IN ('manual','import','fetched')),
    hlc INTEGER NOT NULL, hlc_device TEXT NOT NULL, deleted INTEGER NOT NULL DEFAULT 0 CHECK (deleted IN (0,1)),
    CHECK (base_code <> quote_code)
) STRICT;
INSERT INTO fx_rate_new (id, base_code, quote_code, rate_date, rate, source, hlc, hlc_device, deleted)
SELECT id, base_code, quote_code, rate_date, rate, source, hlc, hlc_device, deleted FROM fx_rate;

CREATE TABLE installment_plan_new (
    id                 TEXT PRIMARY KEY,
    account_id         TEXT NOT NULL,
    purchase_date      TEXT NOT NULL CHECK (purchase_date GLOB '[0-9][0-9][0-9][0-9]-[0-1][0-9]-[0-3][0-9]'),
    total_minor        INTEGER NOT NULL CHECK (total_minor > 0),
    currency_code      TEXT NOT NULL,
    installments       INTEGER NOT NULL CHECK (installments BETWEEN 1 AND 72),
    interest_rate      TEXT NOT NULL DEFAULT '0',
    first_due_month    TEXT NOT NULL CHECK (first_due_month GLOB '[0-9][0-9][0-9][0-9]-[0-1][0-9]'),
    budget_mode        TEXT NOT NULL DEFAULT 'per_installment' CHECK (budget_mode IN ('at_purchase','per_installment')),
    hlc INTEGER NOT NULL, hlc_device TEXT NOT NULL, deleted INTEGER NOT NULL DEFAULT 0 CHECK (deleted IN (0,1)),
    FOREIGN KEY (account_id, currency_code) REFERENCES account(id, currency_code)   -- [D-04]
) STRICT;
INSERT INTO installment_plan_new (id, account_id, purchase_date, total_minor, currency_code, installments,
       interest_rate, first_due_month, budget_mode, hlc, hlc_device, deleted)
SELECT id, account_id, purchase_date, total_minor, currency_code, installments,
       interest_rate, first_due_month, budget_mode, hlc, hlc_device, deleted
FROM installment_plan;

CREATE TABLE recurring_rule_new (
    id             TEXT PRIMARY KEY,
    name           TEXT NOT NULL,
    kind           TEXT NOT NULL CHECK (kind IN ('bill','income','subscription','transfer')),
    rrule          TEXT NOT NULL,
    window_days    INTEGER NOT NULL DEFAULT 0 CHECK (window_days >= 0),
    amount_mode    TEXT CHECK (amount_mode IN ('exact','approximate','range')),
    expected_minor INTEGER,
    tolerance_pct  TEXT,                              -- decimal string, e.g. '10'
    expected_min_minor INTEGER,
    expected_max_minor INTEGER,
    currency_code  TEXT REFERENCES currency(code),
    payee_id       TEXT REFERENCES payee(id),
    description    TEXT NOT NULL DEFAULT '',
    payer_member_id      TEXT REFERENCES member(id),
    attributed_member_id TEXT REFERENCES member(id),
    next_date      TEXT NOT NULL CHECK (next_date GLOB '[0-9][0-9][0-9][0-9]-[0-1][0-9]-[0-3][0-9]'),
    auto_post      INTEGER NOT NULL DEFAULT 0 CHECK (auto_post IN (0,1)),
    hlc INTEGER NOT NULL, hlc_device TEXT NOT NULL, deleted INTEGER NOT NULL DEFAULT 0 CHECK (deleted IN (0,1)),
    CHECK ((amount_mode IS NULL        AND expected_minor IS NULL     AND tolerance_pct IS NULL
                                       AND expected_min_minor IS NULL AND expected_max_minor IS NULL)
        OR (amount_mode = 'exact'      AND expected_minor IS NOT NULL AND tolerance_pct IS NULL
                                       AND expected_min_minor IS NULL AND expected_max_minor IS NULL)
        OR (amount_mode = 'approximate' AND expected_minor IS NOT NULL AND tolerance_pct IS NOT NULL
                                       AND expected_min_minor IS NULL AND expected_max_minor IS NULL)
        OR (amount_mode = 'range'      AND expected_minor IS NULL     AND tolerance_pct IS NULL
                                       AND expected_min_minor IS NOT NULL AND expected_max_minor IS NOT NULL
                                       AND expected_min_minor <= expected_max_minor)),
    CHECK (amount_mode IS NULL OR currency_code IS NOT NULL)
) STRICT;
-- recurring_rule: guard G2 proved it empty (template_json has no defined format to convert), so nothing to copy.

CREATE TABLE import_profile_new (
    id            TEXT PRIMARY KEY,
    name          TEXT NOT NULL,
    format        TEXT NOT NULL CHECK (format IN ('csv','xlsx','pdf')),
    parser_kind   TEXT NOT NULL CHECK (parser_kind IN ('mapping','workbook','builtin','ai')),
    bank          TEXT,
    doc_type      TEXT,
    mapping_json  TEXT,                            -- column-mapping options for parser_kind = 'mapping' (opaque config)
    hlc INTEGER NOT NULL, hlc_device TEXT NOT NULL, deleted INTEGER NOT NULL DEFAULT 0 CHECK (deleted IN (0,1)),
    CHECK (parser_kind <> 'builtin' OR (bank IS NOT NULL AND doc_type IS NOT NULL)),
    CHECK (parser_kind = 'builtin' OR doc_type IS NULL),
    CHECK (parser_kind <> 'mapping' OR mapping_json IS NOT NULL),
    CHECK (parser_kind <> 'workbook' OR format = 'xlsx')
) STRICT;
INSERT INTO import_profile_new (id, name, format, parser_kind, bank, doc_type, mapping_json, hlc, hlc_device, deleted)
SELECT id, name, format,
       CASE WHEN parser LIKE 'builtin:%' THEN 'builtin' ELSE parser END,
       CASE WHEN parser LIKE 'builtin:%'
            THEN substr(substr(parser, 9), 1, instr(substr(parser, 9), ':') - 1)
            ELSE bank END,
       CASE WHEN parser LIKE 'builtin:%'
            THEN substr(substr(parser, 9), instr(substr(parser, 9), ':') + 1)
            ELSE NULL END,
       mapping_json, hlc, hlc_device, deleted
FROM import_profile;

CREATE TABLE import_batch_new (
    id            TEXT PRIMARY KEY,
    account_id    TEXT REFERENCES account(id),
    profile_id    TEXT REFERENCES import_profile(id),
    file_name     TEXT NOT NULL,
    file_sha256   TEXT NOT NULL,
    extractor     TEXT NOT NULL CHECK (extractor IN ('mapping','workbook','builtin','ai')),   -- [D-20] T-28
    ai_provider   TEXT,
    status        TEXT NOT NULL CHECK (status IN ('staged','committed','discarded','reverted')),
    statement_period_start TEXT,
    statement_period_end   TEXT,
    statement_closing_minor INTEGER,
    created_at    TEXT NOT NULL,
    hlc INTEGER NOT NULL, hlc_device TEXT NOT NULL, deleted INTEGER NOT NULL DEFAULT 0 CHECK (deleted IN (0,1)),
    CHECK (statement_closing_minor IS NULL OR account_id IS NOT NULL)          -- closing balance needs a currency
) STRICT;
INSERT INTO import_batch_new (id, account_id, profile_id, file_name, file_sha256, extractor, ai_provider, status,
       statement_period_start, statement_period_end, statement_closing_minor, created_at, hlc, hlc_device, deleted)
SELECT id, account_id, profile_id, file_name, file_sha256, extractor, ai_provider, status,
       statement_period_start, statement_period_end, statement_closing_minor, created_at, hlc, hlc_device, deleted
FROM import_batch;

CREATE TABLE journal_entry_new (
    id               TEXT PRIMARY KEY,
    entry_date       TEXT NOT NULL CHECK (entry_date GLOB '[0-9][0-9][0-9][0-9]-[0-1][0-9]-[0-3][0-9]'),
    kind             TEXT NOT NULL DEFAULT 'regular' REFERENCES entry_kind(code),  -- [D-24]
    payee_id         TEXT REFERENCES payee(id),
    description      TEXT NOT NULL DEFAULT '',
    memo             TEXT NOT NULL DEFAULT '',
    payer_member_id  TEXT REFERENCES member(id),
    attributed_member_id TEXT REFERENCES member(id),
    installment_plan_id TEXT REFERENCES installment_plan(id),
    recurring_rule_id   TEXT REFERENCES recurring_rule(id),
    import_batch_id  TEXT REFERENCES import_batch(id),
    fingerprint      TEXT,
    hlc INTEGER NOT NULL, hlc_device TEXT NOT NULL, deleted INTEGER NOT NULL DEFAULT 0 CHECK (deleted IN (0,1)),
    CHECK ((kind = 'installment_purchase') = (installment_plan_id IS NOT NULL))
) STRICT;
-- kind keeps intent only; expense / income / transfer / split are derived by classify() (D-06).
-- is_shared is dropped (G4 proved it agrees with entry_share); status moves to the account legs (D-11).
INSERT INTO journal_entry_new (id, entry_date, kind, payee_id, description, memo, payer_member_id,
       attributed_member_id, installment_plan_id, recurring_rule_id, import_batch_id, fingerprint,
       hlc, hlc_device, deleted)
SELECT id, entry_date,
       CASE WHEN kind IN ('expense','income','transfer','split') THEN 'regular' ELSE kind END,
       payee_id, description, memo, payer_member_id,
       attributed_member_id, installment_plan_id, recurring_rule_id, import_batch_id, fingerprint,
       hlc, hlc_device, deleted
FROM journal_entry;

CREATE TABLE installment_new (
    id             TEXT PRIMARY KEY,
    plan_id        TEXT NOT NULL REFERENCES installment_plan(id),
    number         INTEGER NOT NULL CHECK (number >= 1),
    due_month      TEXT NOT NULL CHECK (due_month GLOB '[0-9][0-9][0-9][0-9]-[0-1][0-9]'),
    amount_minor   INTEGER NOT NULL CHECK (amount_minor > 0),
    paid_entry_id  TEXT REFERENCES journal_entry(id),
    hlc INTEGER NOT NULL, hlc_device TEXT NOT NULL, deleted INTEGER NOT NULL DEFAULT 0 CHECK (deleted IN (0,1))
) STRICT;
INSERT INTO installment_new (id, plan_id, number, due_month, amount_minor, paid_entry_id, hlc, hlc_device, deleted)
SELECT id, plan_id, number, due_month, amount_minor, paid_entry_id, hlc, hlc_device, deleted FROM installment;

CREATE TABLE reconciliation_new (
    id                      TEXT PRIMARY KEY,
    account_id              TEXT NOT NULL REFERENCES account(id),
    statement_date          TEXT NOT NULL CHECK (statement_date GLOB '[0-9][0-9][0-9][0-9]-[0-1][0-9]-[0-3][0-9]'),
    statement_balance_minor INTEGER NOT NULL,
    status                  TEXT NOT NULL CHECK (status IN ('open','balanced','discrepancy')),
    hlc INTEGER NOT NULL, hlc_device TEXT NOT NULL, deleted INTEGER NOT NULL DEFAULT 0 CHECK (deleted IN (0,1)),
    UNIQUE (id, account_id)                                                     -- [D-11] composite FK target
) STRICT;
INSERT INTO reconciliation_new (id, account_id, statement_date, statement_balance_minor, status, hlc, hlc_device, deleted)
SELECT id, account_id, statement_date, statement_balance_minor, status, hlc, hlc_device, deleted FROM reconciliation;

CREATE TABLE posting_new (
    id                TEXT PRIMARY KEY,
    entry_id          TEXT NOT NULL REFERENCES journal_entry(id),
    leg               TEXT NOT NULL CHECK (leg IN ('account','category','fx')),
    account_id        TEXT,
    category_id       TEXT REFERENCES category(id),
    amount_minor      INTEGER NOT NULL CHECK (amount_minor <> 0),
    currency_code     TEXT NOT NULL REFERENCES currency(code),
    memo              TEXT NOT NULL DEFAULT '',
    status            TEXT CHECK (status IN ('pending','cleared','reconciled')),
    reconciliation_id TEXT,
    hlc INTEGER NOT NULL, hlc_device TEXT NOT NULL, deleted INTEGER NOT NULL DEFAULT 0 CHECK (deleted IN (0,1)),
    CHECK ((leg = 'account'  AND account_id IS NOT NULL AND category_id IS NULL)
        OR (leg = 'category' AND account_id IS NULL     AND category_id IS NOT NULL)
        OR (leg = 'fx'       AND account_id IS NULL     AND category_id IS NULL)),
    CHECK ((leg = 'account') = (status IS NOT NULL)),
    CHECK (leg = 'account' OR reconciliation_id IS NULL),
    CHECK ((status = 'reconciled') = (reconciliation_id IS NOT NULL)),
    FOREIGN KEY (account_id, currency_code) REFERENCES account(id, currency_code),
    FOREIGN KEY (reconciliation_id, account_id) REFERENCES reconciliation(id, account_id)
) STRICT;
-- leg from the old exclusive arc; account legs take the entry's status. 0001 never linked a leg to a
-- reconciliation, so a 'reconciled' entry becomes 'cleared' and is reconciled again (proposal §5, mapping).
INSERT INTO posting_new (id, entry_id, leg, account_id, category_id, amount_minor, currency_code, memo,
       status, reconciliation_id, hlc, hlc_device, deleted)
SELECT p.id, p.entry_id,
       CASE WHEN p.account_id IS NOT NULL THEN 'account' ELSE 'category' END,
       p.account_id, p.category_id, p.amount_minor, p.currency_code, p.memo,
       CASE WHEN p.account_id IS NULL THEN NULL
            WHEN e.status = 'reconciled' THEN 'cleared'
            ELSE e.status END,
       NULL, p.hlc, p.hlc_device, p.deleted
FROM posting p JOIN journal_entry e ON e.id = p.entry_id;

CREATE TABLE entry_share_new (
    id              TEXT PRIMARY KEY,
    entry_id        TEXT NOT NULL REFERENCES journal_entry(id),
    member_id       TEXT REFERENCES member(id),
    participant_id  TEXT REFERENCES external_participant(id),
    amount_minor    INTEGER NOT NULL,
    currency_code   TEXT NOT NULL REFERENCES currency(code),                    -- [D-15]
    settled_entry_id TEXT REFERENCES journal_entry(id),
    hlc INTEGER NOT NULL, hlc_device TEXT NOT NULL, deleted INTEGER NOT NULL DEFAULT 0 CHECK (deleted IN (0,1)),
    CHECK ((member_id IS NULL) <> (participant_id IS NULL))
) STRICT;
-- currency = the entry's single posting currency (G3 proved there is exactly one).
INSERT INTO entry_share_new (id, entry_id, member_id, participant_id, amount_minor, currency_code,
       settled_entry_id, hlc, hlc_device, deleted)
SELECT s.id, s.entry_id, s.member_id, s.participant_id, s.amount_minor,
       (SELECT min(p.currency_code) FROM posting p WHERE p.entry_id = s.entry_id AND p.deleted = 0),
       s.settled_entry_id, s.hlc, s.hlc_device, s.deleted
FROM entry_share s;

CREATE TABLE payee_rule_new (
    id           TEXT PRIMARY KEY,
    priority     INTEGER NOT NULL DEFAULT 100,
    match_kind   TEXT NOT NULL CHECK (match_kind IN ('contains','starts_with','regex','exact')),
    pattern      TEXT NOT NULL,
    account_id   TEXT REFERENCES account(id),
    set_payee_id TEXT REFERENCES payee(id),
    set_category_id TEXT REFERENCES category(id),
    hlc INTEGER NOT NULL, hlc_device TEXT NOT NULL, deleted INTEGER NOT NULL DEFAULT 0 CHECK (deleted IN (0,1)),
    CHECK (set_payee_id IS NOT NULL OR set_category_id IS NOT NULL)            -- [D-12]
) STRICT;
INSERT INTO payee_rule_new (id, priority, match_kind, pattern, account_id, set_payee_id, set_category_id,
       hlc, hlc_device, deleted)
SELECT id, priority, match_kind, pattern, account_id, set_payee_id, set_category_id, hlc, hlc_device, deleted
FROM payee_rule;

CREATE TABLE budget_line_new (
    id             TEXT PRIMARY KEY,
    period         TEXT NOT NULL CHECK (period GLOB '[0-9][0-9][0-9][0-9]-[0-1][0-9]'),
    category_id    TEXT NOT NULL REFERENCES category(id),
    scope          TEXT NOT NULL CHECK (scope IN ('personal','household')),
    member_id      TEXT REFERENCES member(id),
    amount_minor   INTEGER NOT NULL CHECK (amount_minor >= 0),
    currency_code  TEXT NOT NULL REFERENCES currency(code),
    rollover       INTEGER NOT NULL DEFAULT 0 CHECK (rollover IN (0,1)),
    hlc INTEGER NOT NULL, hlc_device TEXT NOT NULL, deleted INTEGER NOT NULL DEFAULT 0 CHECK (deleted IN (0,1)),
    CHECK ((scope = 'personal' AND member_id IS NOT NULL) OR (scope = 'household' AND member_id IS NULL))
) STRICT;
INSERT INTO budget_line_new (id, period, category_id, scope, member_id, amount_minor, currency_code, rollover,
       hlc, hlc_device, deleted)
SELECT id, period, category_id, scope, member_id, amount_minor, currency_code, rollover, hlc, hlc_device, deleted
FROM budget_line;

CREATE TABLE sync_conflict_new (
    id           TEXT PRIMARY KEY,
    entity       TEXT NOT NULL,
    entity_id    TEXT NOT NULL,
    kind         TEXT NOT NULL CHECK (kind IN
                   ('edit_vs_delete','possible_duplicate','reconciled_edit','unbalanced_entry','duplicate_name')),  -- [D-12]
    details_json TEXT NOT NULL,
    resolved     INTEGER NOT NULL DEFAULT 0 CHECK (resolved IN (0,1)),
    created_at   TEXT NOT NULL
) STRICT;
INSERT INTO sync_conflict_new (id, entity, entity_id, kind, details_json, resolved, created_at)
SELECT id, entity, entity_id, kind, details_json, resolved, created_at FROM sync_conflict;

-- ───────────────────────── 4. New tables (recurring templates, D-23) ─────────────────────────
-- Empty: recurring_rule was empty (G2), so there are no templates to convert.
CREATE TABLE recurring_rule_posting (
    id             TEXT PRIMARY KEY,
    rule_id        TEXT NOT NULL REFERENCES recurring_rule(id),
    leg            TEXT NOT NULL CHECK (leg IN ('account','category','fx')),
    account_id     TEXT,
    category_id    TEXT REFERENCES category(id),
    amount_minor   INTEGER NOT NULL CHECK (amount_minor <> 0),
    currency_code  TEXT NOT NULL REFERENCES currency(code),
    memo           TEXT NOT NULL DEFAULT '',
    hlc INTEGER NOT NULL, hlc_device TEXT NOT NULL, deleted INTEGER NOT NULL DEFAULT 0 CHECK (deleted IN (0,1)),
    CHECK ((leg = 'account'  AND account_id IS NOT NULL AND category_id IS NULL)
        OR (leg = 'category' AND account_id IS NULL     AND category_id IS NOT NULL)
        OR (leg = 'fx'       AND account_id IS NULL     AND category_id IS NULL)),
    FOREIGN KEY (account_id, currency_code) REFERENCES account(id, currency_code)
) STRICT;
CREATE TABLE recurring_rule_share (
    id              TEXT PRIMARY KEY,
    rule_id         TEXT NOT NULL REFERENCES recurring_rule(id),
    member_id       TEXT REFERENCES member(id),
    participant_id  TEXT REFERENCES external_participant(id),
    amount_minor    INTEGER NOT NULL,
    currency_code   TEXT NOT NULL REFERENCES currency(code),
    hlc INTEGER NOT NULL, hlc_device TEXT NOT NULL, deleted INTEGER NOT NULL DEFAULT 0 CHECK (deleted IN (0,1)),
    CHECK ((member_id IS NULL) <> (participant_id IS NULL))
) STRICT;

